Read text file `pipeline/resplit.ts`.
1|// Step: re-split scenes where the dominant emotion changes strongly
2|// along the text. Reads book.json and analysis.json, rewrites
3|// scenes.json and analysis.json. Skips when provenance.resplit exists.
4|import { readFileSync, writeFileSync } from "node:fs";
5|import { join } from "node:path";
6|import { renormalize8 } from "../core/emotion";
7|import { countWords } from "../core/reader";
8|import {
9|  RESPLIT_ASK_MARGIN,
10|  RESPLIT_AUTO_MARGIN,
11|  buildWindows,
12|  isResplitCandidate,
13|  meanVector,
14|  planSplits,
15|  splitIds,
16|  topOf,
17|} from "../core/resplit";
18|import type { ResplitWindow, SplitCall } from "../core/resplit";
19|import { validateBookCoverage } from "../core/scenes";
20|import type { AnalyzedScene, Book, EmotionId, Scene, SceneEmotion } from "../core/types";
21|import { classifyScene } from "./classify";
22|import type { ClassifyMetaUsage } from "./classify";
23|import type { StepCtx } from "./ingest";
24|import { runPool } from "./http";
25|import type { JevClient } from "./jev";
26|import type { MetaClient } from "./meta";
27|import { jevCostUsd, metaCostUsd } from "./prices";
28|
29|const DECISION_SCHEMA = {
30|  type: "object",
31|  properties: { split: { type: "boolean" }, reason: { type: "string" } },
32|  required: ["split", "reason"],
33|  additionalProperties: false,
34|};
35|
36|const TITLES_SCHEMA = {
37|  type: "object",
38|  properties: {
39|    parts: {
40|      type: "array",
41|      items: {
42|        type: "object",
43|        properties: {
44|          start_n: { type: "number" },
45|          end_n: { type: "number" },
46|          title: { type: "string" },
47|          summary: { type: "string" },
48|          characters: { type: "array", items: { type: "string" } },
49|        },
50|        required: ["start_n", "end_n", "title", "summary", "characters"],
51|        additionalProperties: false,
52|      },
53|    },
54|  },
55|  required: ["parts"],
56|  additionalProperties: false,
57|};
58|
59|export interface ResplitEntry {
60|  from: string;
61|  at_n: number;
62|  margin: number;
63|  window_left: EmotionId;
64|  window_right: EmotionId;
65|  final_left: EmotionId | null;
66|  final_right: EmotionId | null;
67|  decided_by: "rule" | "muse";
68|  reason?: string;
69|}
70|
71|export interface ResplitRejected {
72|  from: string;
73|  at_n: number;
74|  margin: number;
75|  window_left: EmotionId;
76|  window_right: EmotionId;
77|  reason: string;
78|}
79|
80|export interface ResplitMergedBack {
81|  from: string;
82|  top: EmotionId | null;
83|}
84|
85|interface Usage {
86|  jevRequests: number;
87|  jevInputTokens: number;
88|  jevOutputTokens: number;
89|  meta: ClassifyMetaUsage;
90|}
91|
92|function newUsage(model: string): Usage {
93|  return { jevRequests: 0, jevInputTokens: 0, jevOutputTokens: 0, meta: { model, requests: 0, promptTokens: 0, cachedTokens: 0, completionTokens: 0, costUsd: 0 } };
94|}
95|
96|function trackMeta(usage: Usage, result: { promptTokens: number; cachedTokens: number; completionTokens: number }): void {
97|  usage.meta.requests += 1;
98|  usage.meta.promptTokens += result.promptTokens;
99|  usage.meta.cachedTokens += result.cachedTokens;
100|  usage.meta.completionTokens += result.completionTokens;
101|}
102|
103|export async function runResplit(ctx: StepCtx, deps: { jev: JevClient; meta: MetaClient }): Promise<AnalyzedScene[]> {
104|  const book = JSON.parse(readFileSync(join(ctx.dir, "book.json"), "utf8")) as Book;
105|  const scenesFile = JSON.parse(readFileSync(join(ctx.dir, "scenes.json"), "utf8")) as {
106|    bookId: string;
107|    textVersion: string;
108|    scenes: Scene[];
109|    provenance: { meta: { model: string; requests: number; prompt_tokens: number; cached_tokens: number; completion_tokens: number; cost_usd: number } };
110|  };
111|  const analysisFile = JSON.parse(readFileSync(join(ctx.dir, "analysis.json"), "utf8")) as {
112|    bookId: string;
113|    textVersion: string;
114|    scenes: AnalyzedScene[];
115|    provenance: {
116|      date: string;
117|      jev: { model: string; requests: number; input_tokens: number; output_tokens: number; cost_usd: number };
118|      meta: { model: string; requests: number; prompt_tokens: number; cached_tokens: number; completion_tokens: number; cost_usd: number };
119|      total_cost_usd: number;
120|      resplit?: unknown;
121|    };
122|  };
123|  if (!ctx.force && analysisFile.textVersion === book.textVersion && analysisFile.provenance.resplit) {
124|    return analysisFile.scenes;
125|  }
126|  const usage = newUsage(deps.meta.model);
127|  const byN = new Map(book.paragraphs.map((p) => [p.n, p.text]));
128|  const chapterTitle = new Map(book.chapters.map((c) => [c.ch, c.title]));
129|  const wordsOf = (scene: { start_n: number; end_n: number }): number => {
130|    let words = 0;
131|    for (let n = scene.start_n; n <= scene.end_n; n++) words += countWords(byN.get(n) ?? "");
132|    return words;
133|  };
134|  const candidates = analysisFile.scenes.filter((s) => isResplitCandidate(wordsOf(s), s.final));
135|  let windowsClassified = 0;
136|  const windowFailures: string[] = [];
137|  const rejected: ResplitRejected[] = [];
138|  const mergedBack: ResplitMergedBack[] = [];
139|
140|  const splitScenes = await runPool(candidates, 4, async (scene) => {
141|    const paragraphs = book.paragraphs.filter((p) => p.n >= scene.start_n && p.n <= scene.end_n);
142|    const spans = buildWindows(paragraphs);
143|    const windows: ResplitWindow[] = [];
144|    for (const span of spans) {
145|      const text = paragraphs.filter((p) => p.n >= span.startN && p.n <= span.endN).map((p) => p.text).join("\n");
146|      let result;
147|      try {
148|        result = await deps.jev.classify({ book: book.title, chapter: chapterTitle.get(scene.ch) ?? "", sceneTitle: scene.title, scene: text });
149|      } catch {
150|        windowFailures.push(scene.id);
151|        return null;
152|      }
153|      usage.jevRequests += 1;
154|      usage.jevInputTokens += result.input_tokens;
155|      usage.jevOutputTokens += result.output_tokens;
156|      const { unknown: _dropped, ...rest } = result.vector;
157|      const vector = renormalize8(rest);
158|      if (vector === null) {
159|        windowFailures.push(scene.id);
160|        return null;
161|      }
162|      windows.push({ ...span, vector });
163|      windowsClassified += 1;
164|    }
165|    if (windows.length < 2) return null;
166|    const taken: { call: SplitCall; by: "rule" | "muse" }[] = [];
167|    const reasons = new Map<number, string>();
168|    const cuts = await planSplits(
169|      windows,
170|      async (call) => {
171|        const boundaryN = windows[call.index]?.startN ?? 0;
172|        const before = paragraphs.filter((p) => p.n < boundaryN).slice(-2);
173|        const after = paragraphs.filter((p) => p.n >= boundaryN).slice(0, 2);
174|        const left = meanVector(windows.slice(0, call.index));
175|        const right = meanVector(windows.slice(call.index));
176|        const result = await deps.meta.completeJson({
177|          system: "You judge whether a scene needs two music tracks. Answer with JSON only.",
178|          user:
179|            `Scene "${scene.title}" may change mood at paragraph ${windows[call.index]?.startN}. ` +
180|            `Left mood ${call.left} ${JSON.stringify(left)}, right mood ${call.right} ${JSON.stringify(right)}. ` +
181|            `Split only when the dominant feeling changes strongly and stays changed, not for a mixed blend. ` +
182|            `Before: ${before.map((p) => `[${p.n}] ${p.text}`).join("\n")}\nAfter: ${after.map((p) => `[${p.n}] ${p.text}`).join("\n")}`,
183|          schemaName: "resplit_decision",
184|          schema: DECISION_SCHEMA,
185|        });
186|        trackMeta(usage, result);
187|        const data = result.data as { split?: unknown; reason?: unknown };
188|        const split = data.split === true;
189|        const reason = String(data.reason ?? "");
190|        if (split) reasons.set(call.index, reason);
191|        else rejected.push({ from: scene.id, at_n: boundaryN, margin: call.margin, window_left: call.left, window_right: call.right, reason });
192|        return split;
193|      },
194|      (call, by) => taken.push({ call, by }),
195|    );
196|    if (cuts.length === 0) return null;
197|    const bounds = [0, ...cuts, windows.length];
198|    const ranges = bounds.slice(1).map((end, i) => ({ startN: windows[bounds[i] ?? 0]?.startN ?? 0, endN: windows[end - 1]?.endN ?? 0 }));
199|    const result = await deps.meta.completeJson({
200|      system: "You split a book scene into ordered parts. Answer with JSON only, English titles in the style of the existing scene titles.",
201|      user:
202|        `Scene "${scene.title}" (${scene.id}, summary: ${scene.summary}) splits into ${ranges.length} parts. ` +
203|        `Give each part start_n, end_n, title, summary, and characters.\n` +
204|        ranges.map((r, i) => `PART ${i + 1} [${r.startN}..${r.endN}]:\n${paragraphs.filter((p) => p.n >= r.startN && p.n <= r.endN).map((p) => `[${p.n}] ${p.text}`).join("\n")}`).join("\n"),
205|      schemaName: "resplit_titles",
206|      schema: TITLES_SCHEMA,
207|    });
208|    trackMeta(usage, result);
209|    const parts = (result.data as { parts?: { start_n: number; end_n: number; title: string; summary: string; characters: unknown }[] }).parts ?? [];
210|    if (parts.length !== ranges.length || parts.some((p, i) => p.start_n !== ranges[i]?.startN || p.end_n !== ranges[i]?.endN)) {
211|      throw new Error(`scene ${scene.id} titles do not cover the split ranges`);
212|    }
213|    const bases = parts.map((part) => ({
214|      ch: scene.ch,
215|      start_n: part.start_n,
216|      end_n: part.end_n,
217|      title: part.title,
218|      summary: part.summary,
219|      characters: Array.isArray(part.characters) ? part.characters.map(String) : [],
220|    }));
221|    const analyzed = await runPool(bases, 4, async (base) => {
222|      const text = paragraphs.filter((p) => p.n >= base.start_n && p.n <= base.end_n).map((p) => p.text).join("\n");
223|      const emotion = await classifyScene({ id: "", ...base }, text, book.title, chapterTitle.get(scene.ch) ?? "", deps, usage.meta);
224|      if (emotion.jev) {
225|        usage.jevRequests += 1;
226|        usage.jevInputTokens += emotion.jev.input_tokens;
227|        usage.jevOutputTokens += emotion.jev.output_tokens;
228|      }
229|      return emotion;
230|    });
231|    // Merge adjacent parts whose re-classified top emotion agrees; a
232|    // null final never merges. One extra classify per merged group.
233|    const tops = analyzed.map((e) => (e.final ? topOf(e.final.vector).id : null));
234|    const groups: number[][] = [];
235|    for (let i = 0; i < bases.length; i++) {
236|      const last = groups[groups.length - 1];
237|      const prev = last ? tops[last[last.length - 1] ?? -1] : undefined;
238|      const top = tops[i];
239|      if (last && top !== null && top === prev) last.push(i);
240|      else groups.push([i]);
241|    }
242|    if (groups.length === 1 && bases.length > 1) {
243|      mergedBack.push({ from: scene.id, top: tops[0] ?? null });
244|      return null;
245|    }
246|    const finals: { base: (typeof bases)[number]; emotion: SceneEmotion }[] = [];
247|    for (const group of groups) {
248|      if (group.length === 1) {
249|        const i = group[0] ?? 0;
250|        finals.push({ base: bases[i]!, emotion: (analyzed[i] ?? { jev: null, muse_override: null, final: null, error: "missing part emotion" }) as SceneEmotion });
251|        continue;
252|      }
253|      const first = bases[group[0] ?? 0]!;
254|      const lastBase = bases[group[group.length - 1] ?? 0]!;
255|      const base = { ...first, start_n: first.start_n, end_n: lastBase.end_n };
256|      const text = paragraphs.filter((p) => p.n >= base.start_n && p.n <= base.end_n).map((p) => p.text).join("\n");
257|      const emotion = await classifyScene({ id: "", ...base }, text, book.title, chapterTitle.get(scene.ch) ?? "", deps, usage.meta);
258|      if (emotion.jev) {
259|        usage.jevRequests += 1;
260|        usage.jevInputTokens += emotion.jev.input_tokens;
261|        usage.jevOutputTokens += emotion.jev.output_tokens;
262|      }
263|      finals.push({ base, emotion });
264|      mergedBack.push({ from: scene.id, top: emotion.final ? topOf(emotion.final.vector).id : null });
265|    }
266|    const ids = splitIds(scene.id, finals.length);
267|    const byCut = new Map(taken.map((t) => [t.call.index, t]));
268|    const finalTops = finals.map((f) => (f.emotion.final ? topOf(f.emotion.final.vector).id : null));
269|    // One entry per surviving cut; the window tops picked the cut and
270|    // the final tops are what the stored parts re-classified to.
271|    const entries: ResplitEntry[] = [];
272|    let start = 0;
273|    for (let g = 0; g + 1 < groups.length; g++) {
274|      const end = start + (groups[g]?.length ?? 0);
275|      const cutIndex = bounds[end] ?? 0;
276|      const call = byCut.get(cutIndex);
277|      const reason = reasons.get(cutIndex);
278|      entries.push({
279|        from: scene.id,
280|        at_n: finals[g + 1]?.base.start_n ?? 0,
281|        margin: call?.call.margin ?? 0,
282|        window_left: call?.call.left ?? "calma",
283|        window_right: call?.call.right ?? "calma",
284|        final_left: finalTops[g] ?? null,
285|        final_right: finalTops[g + 1] ?? null,
286|        decided_by: call?.by ?? "rule",
287|        ...(reason ? { reason } : {}),
288|      });
289|      start = end;
290|    }
291|    return {
292|      scene,
293|      parts: finals.map((f, i) => ({
294|        scene: { id: ids[i] ?? "", ...f.base } satisfies Scene,
295|        emotion: f.emotion,
296|      })),
297|      entries,
298|    };
299|  });
300|
301|  const byId = new Map(splitScenes.filter((s) => s !== null).map((s) => [s.scene.id, s]));
302|  const scenes: AnalyzedScene[] = [];
303|  const entries: ResplitEntry[] = [];
304|  for (const old of analysisFile.scenes) {
305|    const split = byId.get(old.id);
306|    if (!split) {
307|      scenes.push(old);
308|      continue;
309|    }
310|    entries.push(...split.entries);
311|    for (const part of split.parts) scenes.push({ ...part.scene, ...part.emotion });
312|  }
313|  scenes.sort((a, b) => a.start_n - b.start_n);
314|  const seen = new Set<string>();
315|  for (const s of scenes) {
316|    if (seen.has(s.id)) throw new Error(`resplit minted duplicate scene id ${s.id}`);
317|    seen.add(s.id);
318|  }
319|  const problems = validateBookCoverage(book, scenes);
320|  if (problems.length > 0) throw new Error(`resplit breaks coverage: ${problems.map((p) => p.message).join("; ")}`);
321|
322|  usage.meta.costUsd = metaCostUsd({ prompt: usage.meta.promptTokens, cached: usage.meta.cachedTokens, completion: usage.meta.completionTokens });
323|  const jevCost = jevCostUsd(usage.jevInputTokens);
324|  const prevJev = analysisFile.provenance.jev;
325|  const prevMeta = analysisFile.provenance.meta;
326|  const segmentMeta = scenesFile.provenance.meta;
327|  writeFileSync(
328|    join(ctx.dir, "scenes.json"),
329|    `${JSON.stringify({
330|      bookId: book.id,
331|      textVersion: book.textVersion,
332|      scenes: scenes.map(({ id, ch, start_n, end_n, title, summary, characters }) => ({ id, ch, start_n, end_n, title, summary, characters })),
333|      provenance: {
334|        date: new Date().toISOString(),
335|        meta: {
336|          model: segmentMeta.model,
337|          requests: segmentMeta.requests + usage.meta.requests,
338|          prompt_tokens: segmentMeta.prompt_tokens + usage.meta.promptTokens,
339|          cached_tokens: segmentMeta.cached_tokens + usage.meta.cachedTokens,
340|          completion_tokens: segmentMeta.completion_tokens + usage.meta.completionTokens,
341|          cost_usd: segmentMeta.cost_usd + usage.meta.costUsd,
342|        },
343|      },
344|    })}\n`,
345|  );
346|  const totalJev = { model: deps.jev.model, requests: prevJev.requests + usage.jevRequests, input_tokens: prevJev.input_tokens + usage.jevInputTokens, output_tokens: prevJev.output_tokens + usage.jevOutputTokens, cost_usd: prevJev.cost_usd + jevCost };
347|  const totalMeta = {
348|    model: prevMeta.model,
349|    requests: prevMeta.requests + usage.meta.requests,
350|    prompt_tokens: prevMeta.prompt_tokens + usage.meta.promptTokens,
351|    cached_tokens: prevMeta.cached_tokens + usage.meta.cachedTokens,
352|    completion_tokens: prevMeta.completion_tokens + usage.meta.completionTokens,
353|    cost_usd: prevMeta.cost_usd + usage.meta.costUsd,
354|  };
355|  const overrides = scenes.filter((s) => s.muse_override !== null).length;
356|  writeFileSync(
357|    join(ctx.dir, "analysis.json"),
358|    `${JSON.stringify({
359|      bookId: book.id,
360|      textVersion: book.textVersion,
361|      scenes,
362|      override_rate: scenes.length > 0 ? overrides / scenes.length : 0,
363|      provenance: {
364|        date: new Date().toISOString(),
365|        jev: totalJev,
366|        meta: totalMeta,
367|        total_cost_usd: totalJev.cost_usd + totalMeta.cost_usd,
368|        resplit: {
369|          auto_margin: RESPLIT_AUTO_MARGIN,
370|          ask_margin: RESPLIT_ASK_MARGIN,
371|          candidates: candidates.length,
372|          windows_classified: windowsClassified,
373|          splits: entries,
374|          merged_back: mergedBack,
375|          rejected: rejected,
376|          window_failures: windowFailures,
377|          jev: { model: deps.jev.model, requests: usage.jevRequests, input_tokens: usage.jevInputTokens, output_tokens: usage.jevOutputTokens, cost_usd: jevCost },
378|          meta: { model: usage.meta.model, requests: usage.meta.requests, prompt_tokens: usage.meta.promptTokens, cached_tokens: usage.meta.cachedTokens, completion_tokens: usage.meta.completionTokens, cost_usd: usage.meta.costUsd },
379|        },
380|      },
381|    })}\n`,
382|  );
383|  return scenes;
384|}

