1|// Pre-commit size check: staged files must stay under 5000 tokens.
2|// Tokens = ceil(bytes / 4). Plain Node, no dependencies.
3|import { execFileSync } from 'node:child_process';
4|import { fileURLToPath } from 'node:url';
5|
6|export const MAX_TOKENS = 5000;
7|export const BYTES_PER_TOKEN = 4;
8|
9|// Paths the size check skips. Entries ending in "/" match that directory
10|// anywhere in the path. Entries with "*" match the file name. Other entries
11|// match the full path or the file name. Add a pattern here (and say why in
12|// the commit message) when a file really is generated or third-party.
13|export const IGNORE_PATTERNS = [
14|  // Lockfiles: not authored by agents.
15|  'package-lock.json',
16|  'pnpm-lock.yaml',
17|  'yarn.lock',
18|  'bun.lockb',
19|  'uv.lock',
20|  'poetry.lock',
21|  '*.lock',
22|  // Codegen: generated dirs cover their *.d.ts files too.
23|  '*.generated.*',
24|  '*.gen.*',
25|  'next-env.d.ts',
26|  'generated/',
27|  '__generated__/',
28|  // Build output.
29|  '.next/',
30|  'dist/',
31|  'out/',
32|  'coverage/',
33|  // Processed book data, and all of public/.
34|  'public/',
35|  'data/processed/',
36|  // Processed book data (book.json is generated, about 230 KB).
37|  'data/books/',
38|  'pipeline/out/',
39|  // Music library data: track metadata and an etiquetar export, not code.
40|  'data/music/',
41|  // Agent and session logs (the project log dir is agent-logs/).
42|  'agent-logs/',
43|  // Vendored third-party skills.
44|  '.agents/skills/',
45|];
46|
47|function globToRegExp(glob) {
48|  return new RegExp('^' + glob.split('*').map(escapeRegExp).join('.*') + '$');
49|}
50|
51|function escapeRegExp(text) {
52|  return text.replace(/[.+?^${}()|[\]\\]/g, '\\$&');
53|}
54|
55|function basename(path) {
56|  const index = path.lastIndexOf('/');
57|  return index === -1 ? path : path.slice(index + 1);
58|}
59|
60|export function isIgnored(path) {
61|  const name = basename(path);
62|  for (const pattern of IGNORE_PATTERNS) {
63|    if (pattern.endsWith('/')) {
64|      if (path === pattern.slice(0, -1) || path.startsWith(pattern) || path.includes('/' + pattern)) {
65|        return true;
66|      }
67|    } else if (pattern.includes('*')) {
68|      if (globToRegExp(pattern).test(name)) return true;
69|    } else if (path === pattern || name === pattern || path.endsWith('/' + pattern)) {
70|      return true;
71|    }
72|  }
73|  return false;
74|}
75|
76|export function estimateTokens(bytes) {
77|  return Math.ceil(bytes / BYTES_PER_TOKEN);
78|}
79|
80|// Pure and testable: entries look like { path, bytes, isBinary }.
81|export function findOversized(entries) {
82|  const oversized = [];
83|  for (const entry of entries) {
84|    if (entry.isBinary || isIgnored(entry.path)) continue;
85|    const tokens = estimateTokens(entry.bytes);
86|    if (tokens > MAX_TOKENS) oversized.push({ path: entry.path, bytes: entry.bytes, tokens });
87|  }
88|  return oversized;
